static __poll_t gnss_poll ( struct file * file , poll_table * wait ) { struct gnss_device * gdev = file -> private_data ; __poll_t mask = 0 ; poll_wait ( file , & gdev -> read_queue , wait ) ; if ( ! kfifo_is_empty ( & gdev -> read_fifo ) ) { mask |= EPOLLIN | EPOLLRDNORM ; } if ( gdev -> disconnected ) { mask |= EPOLLHUP ; } return mask ; } static const struct file_operations gnss_fops = { . owner = THIS_MODULE . open = gnss_open . release = gnss_release . read = gnss_read . write = gnss_write . poll = gnss_poll . llseek = no_llseek } ; static struct class * gnss_class ; static void gnss_device_release ( struct device * dev ) { struct gnss_device * gdev = to_gnss_device ( dev ) ; kfifo_free ( & gdev -> read_fifo ) ; ida_free ( & gnss_minors , gdev -> id ) ; kfree ( gdev ) ; } 